"""Combined Water/BSF release assets and documentation generated from authoritative app/."""
import hashlib
import importlib.metadata
import json
from pathlib import Path

from app.core.config import APP_DIR, WATER_QUALITY_ROOT


def build_water(service, copy, write, digest):
    from app.services.water_quality import WaterQualityService
    from app.services.water_core import load_local, PARAMETERS
    # No app history is needed for release curation.
    from app.services.water_quality import ReplayStore
    from app.services.water_core import WaterQualityEngine
    engine = WaterQualityEngine()
    data = load_local()
    store = ReplayStore(engine,data,engine.manifest)
    period = store.periods()[0]
    import pandas as pd
    seed = data[data.timestamp.between(pd.Timestamp(period["start"])-pd.Timedelta(hours=3),pd.Timestamp(period["end"]))].copy()
    if seed.empty:
        raise ValueError("Eligible Water seed unavailable")
    seed["segment_id"] = "local_recorded_continuous_v1"
    seed["sensor_id"] = "UNKNOWN"
    for p in PARAMETERS:
        seed[p+"_missing"] = seed[p].isna()
    seed["timezone"] = "Asia/Jakarta"
    path = service / "water_assets/replay/water_replay_v1.csv"
    path.parent.mkdir(parents=True,exist_ok=True)
    seed.to_csv(path,index=False,lineterminator="\n",date_format="%Y-%m-%dT%H:%M:%S",float_format="%.17g")
    meta = {"version":"water_replay_v1","sha256":digest(path),"rows":len(seed),"columns":list(seed.columns),
        "source":"Local Fiscycle recorded sensor measurements", "source_file_sha256":digest(WATER_QUALITY_ROOT / "data/local.csv"),
        "distribution":"AUTHORIZED_LOCAL_DEVELOPER_HANDOVER_ONLY; no public license granted",
        "authorization":"Current explicit all-model/all-replay local handover request; no publication authorized",
        "evaluation_scope":"RETROSPECTIVE_SELECTED_REPLAY_NOT_INDEPENDENT_VALIDATION",
        "independent_validation":False,"timezone":"Asia/Jakarta","timestamp_semantics":"naive local WIB",
        "warmup_hours":3,"period":period,"sensor_identity":"UNKNOWN","pond_identity":"UNKNOWN_SINGLE_RECORDED_GROUP",
        "units":{"ph":"pH","temperature_c":"degC","turbidity_ntu":"NTU"},
        "calibration":"NTU confirmed by product owner; equipment conversion/clipping unverified",
        "missingness":"*_missing booleans; no forward-fill","minimum_replay_origin":engine.manifest["minimum_replay_origin"]}
    write(path.with_suffix(".metadata.json"),json.dumps(meta,indent=2)+"\n")
    write(path.parent / "segment_index.json",json.dumps([period],indent=2)+"\n")
    write(path.parent / "DATA_DICTIONARY.md","# Water replay\n\nTimestamp: local wall clock WIB. pH, temperature_c (degC), turbidity_ntu (NTU): recorded readings, not simulated. source_row_id preserves raw row identity. source_dataset and pond_id preserve provenance; unknown pond ID is a grouping identifier, not an installed pond integration. sensor_id UNKNOWN. segment_id marks the curated continuous sequence. *_missing reflects missingness. No DO, TAN, physical sensor calibration or live link is inferred. Three hours precede the selectable interval for causal warmup. See metadata for permissions and retrospective scope.\n")
    root = WATER_QUALITY_ROOT / "models/mvp_v2"
    copy(root / "manifest.json",service / "water_assets/models/mvp_v2/manifest.json")
    for entry in engine.manifest["models"]:
        if entry["path"]:
            copy(root / entry["path"],service / "water_assets/models/mvp_v2" / entry["path"])
    # Read-only exact inference reference from the selected segment, compared with research engine in tests.
    visible = seed[seed.timestamp.le(pd.Timestamp(period["start"]))]
    payload = {"mode":"historical_replay","pond_id":period["pond_id"],"current_timestamp":period["start"],
        "readings":[{"timestamp":r.timestamp.isoformat(),**{p:getattr(r,p) for p in PARAMETERS}} for r in visible.itertuples()]}
    result = engine.infer(payload)
    write(service / "fixtures/water_reference.json",json.dumps({"input":payload,"expected_forecasts":result["forecasts"]},indent=2)+"\n")
    return meta


